package com.example.bandlink.service;
import org.springframework.web.multipart.MultipartFile; import org.springframework.stereotype.Service; import java.io.*; import java.nio.file.*; import java.util.*;
@Service public class ImageStorageService {private static final long MAX=5*1024*1024; private static final Set<String> TYPES=Set.of("image/jpeg","image/png","image/webp"); private final Path root=Paths.get(System.getenv().getOrDefault("BANDLINK_UPLOAD_DIR","uploads")); public String store(MultipartFile file){if(file==null||file.isEmpty()||file.getSize()>MAX||!TYPES.contains(file.getContentType()))throw new IllegalArgumentException("画像はjpg/png/webp、1枚5MBまでです");try{Files.createDirectories(root);String ext=switch(file.getContentType()){case "image/jpeg"->".jpg";case "image/png"->".png";default->".webp";};String name=UUID.randomUUID()+ext;Files.copy(file.getInputStream(),root.resolve(name),StandardCopyOption.REPLACE_EXISTING);return "/uploads/"+name;}catch(IOException e){throw new IllegalStateException("画像保存に失敗しました",e);}}}
